package com.yihe.framework.ehr;
import java.util.*;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
/** Allowlisted pseudonymous model context. This is pseudonymisation, not an anonymisation guarantee. */
final class AssessmentPrivacy {
 static final String TEST_SUBJECT="SUB-TEST-0001";
 static class Context{final Map<String,Object> model;final Map<String,String> itemIds=new LinkedHashMap<>();Context(Map<String,Object> model){this.model=model;}}
 @SuppressWarnings("unchecked") static Context prepare(Map<String,Object> source,String subject){
  require(subject!=null&&subject.matches("SUB-[A-Za-z0-9-]{8,44}"),503,"AI_SUBJECT_REFERENCE_MISSING");Map<String,Object> person=(Map<String,Object>)source.get("person");Redactor redact=new Redactor(source);Map<String,Object> safePerson=map("subject_ref",subject);if(person.get("age") instanceof Number)safePerson.put("age",person.get("age"));else if(str(person.get("age")).matches("[0-9]{1,3}"))safePerson.put("age",Integer.parseInt(str(person.get("age"))));safePerson.put("sex",ReportMatchingService.sexKey(person.get("sex")));safePerson.put("job",redact.text(person.get("job")));safePerson.put("exposure",redact.text(person.get("exposure")));
  Context context=new Context(map("subject_ref",subject,"person",safePerson));context.model.put("report",report((Map<String,Object>)source.get("report"),"CURRENT","C",redact,context));List<Object> history=new ArrayList<>();int n=0;for(Object prior:(List<?>)source.get("history"))history.add(report((Map<String,Object>)prior,"HISTORY-"+(++n),"H"+n,redact,null));context.model.put("history",history);
  List<String> required=new ArrayList<>();Set<String> seen=new HashSet<>();for(Object raw:(List<?>)((Map<?,?>)context.model.get("report")).get("items")){Map<?,?> item=(Map<?,?>)raw;if(AiHealthReport.abnormal(item)&&seen.add(AiHealthReport.observationKey(item)))required.add(str(item.get("id")));}context.model.put("requiredIndicatorIds",required);return context;
 }
 @SuppressWarnings("unchecked") static Map<String,Object> report(Map<String,Object> raw,String alias,String prefix,Redactor redact,Context context){Map<String,Object> compact=AiHealthReport.compactReport(raw),result=map("id","REPORT-"+alias);for(String key:Arrays.asList("revision","reviewStatus","published","medicalReviewPending","withheldItemCount","unreportedItemCount","originalItemCount"))if(compact.containsKey(key))result.put(key,compact.get(key));List<Object> items=new ArrayList<>();int ordinal=0;
  for(Object value:(List<?>)compact.get("items")){Map<?,?> item=(Map<?,?>)value;String id="OBS-"+prefix+"-"+String.format(java.util.Locale.ROOT,"%04d",++ordinal);if(context!=null)context.itemIds.put(id,str(item.get("id")));Map<String,Object> safe=map("id",id,"page",item.get("page"),"sourcePages",item.get("sourcePages"));for(String key:Arrays.asList("name","value","unit","referenceRange","abnormal"))safe.put(key,redact.text(item.get(key)));items.add(safe);}result.put("items",items);
  for(String section:Arrays.asList("conclusions","advice")){List<Object> entries=new ArrayList<>();Object rows=compact.get(section);if(rows instanceof List)for(Object entry:(List<?>)rows)if(entry instanceof Map){Map<?,?> row=(Map<?,?>)entry;Map<String,Object> safe=new LinkedHashMap<>();for(String key:Arrays.asList("text","label","completeness"))if(row.containsKey(key))safe.put(key,redact.text(row.get(key)));if(row.containsKey("page"))safe.put("page",row.get("page"));entries.add(safe);}result.put(section,entries);}return result;
 }
 static class Redactor{
  final Set<String> literals=new LinkedHashSet<>();
  @SuppressWarnings("unchecked") Redactor(Map<String,Object> source){Map<?,?> p=(Map<?,?>)source.get("person");for(String key:Arrays.asList("name","org","organization","birth"))add(p.get(key));String birth=str(p.get("birth"));try{java.time.LocalDate date=java.time.LocalDate.parse(birth);add(date.toString().replace('-','/'));add(date.getYear()+"年"+date.getMonthValue()+"月"+date.getDayOfMonth()+"日");}catch(Exception ignored){}List<Object> reports=new ArrayList<>();reports.add(source.get("report"));reports.addAll((List<?>)source.get("history"));for(Object value:reports){Map<?,?> report=(Map<?,?>)value;add(report.get("institution"));Object fields=report.get("fieldValues");if(fields instanceof List)for(Object raw:(List<?>)fields)if(raw instanceof Map){Map<?,?> field=(Map<?,?>)raw;String key=str(field.containsKey("field_key")?field.get("field_key"):field.containsKey("key")?field.get("key"):field.get("fieldKey"));if(Arrays.asList("full_name","birth_date","employer").contains(key))add(field.containsKey("value_raw")?field.get("value_raw"):field.get("value"));}}}
  void add(Object value){String s=str(value).trim();if(s.length()>=2)literals.add(s);}
  String text(Object value){String text=str(value);List<String> ordered=new ArrayList<>(literals);ordered.sort((a,b)->Integer.compare(b.length(),a.length()));for(String literal:ordered)text=text.replace(literal,"[身份信息已移除]");return text.replaceAll("(?<![0-9])[12][0-9]{3}[-/.年][0-9]{1,2}[-/.月][0-9]{1,2}日?(?![0-9])","[日期已移除]").replaceAll("(?<![0-9])(?:[0-9]{17}[0-9Xx]|[0-9]{15})(?![0-9])","[证件号已移除]").replaceAll("(?<![0-9])1[3-9][0-9]{9}(?![0-9])","[手机号已移除]").replaceAll("(?i)(?:工号|员工编号|职工编号)\\s*[:：]?\\s*[A-Z0-9_-]{2,40}","[职工编号已移除]").replaceAll("(?:姓名|受检者|患者姓名|职工姓名|签名|检查医生|审核医生|医师签名|单位名称|出生日期)\\s*[:：]\\s*[^\\n；;，,。]{1,80}","[身份信息已移除]").replaceAll("(?i)\\b[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\\b","[内部编号已移除]");}
 }
}
